WITH unpacked AS (SELECT id, customer_id, created_at, items, ship_to, attributes, ship_to.city AS ship_city, attributes['device'] AS device, ARRAY_CONTAINS(MAP_KEYS(attributes), 'weight_kg') AS has_weight_kg, TRANSFORM(items, item -> item.product_id) AS product_ids FROM carts) SELECT id, customer_id, created_at, has_weight_kg, LAST_VALUE(device, TRUE) OVER (PARTITION BY customer_id ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_device, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at, id) AS seq_no, ROW_NUMBER() OVER w_recent AS event_seq, FIRST_VALUE(device) IGNORE NULLS OVER (PARTITION BY ship_city ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_device FROM unpacked WINDOW w_recent AS (PARTITION BY customer_id, ship_city ORDER BY created_at DESC, id);
